gqZ(){return"\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \xab\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c Cursus \u0432 Claude\xbb: \u043e\u0442\u043a\u0440\u043e\u0435\u0442\u0441\u044f \u0441\u0442\u0440\u0430\u043d\u0438\u0446\u0430 Claude (\u043d\u0430 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435 \u2014 \u0432 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435) \u0441 \u0443\u0436\u0435 \u0437\u0430\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u044b\u043c \u043a\u043e\u043d\u043d\u0435\u043a\u0442\u043e\u0440\u043e\u043c. \u041f\u0440\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u0432\u043e\u0439\u0434\u0438\u0442\u0435 \u0432 Claude."},
gqY(){return"\u041f\u0440\u043e\u0432\u0435\u0440\u044c\u0442\u0435 \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 \u0438 \u0430\u0434\u0440\u0435\u0441 \u0438 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 \u043a\u043d\u043e\u043f\u043a\u043e\u0439 \xab\u0414\u043e\u0431\u0430\u0432\u0438\u0442\u044c\xbb."},
gr_(){return"\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \xab\u041f\u043e\u0434\u043a\u043b\u044e\u0447\u0438\u0442\u044c\xbb \u0438 \u0432\u043e\u0439\u0434\u0438\u0442\u0435 \u0441 \u0442\u0435\u043c \u0436\u0435 \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u043e\u043c, \u0447\u0442\u043e \u0438 \u0432 Cursus. \u041f\u043e\u0441\u043b\u0435 \u044d\u0442\u043e\u0433\u043e \u043a\u043e\u043d\u043d\u0435\u043a\u0442\u043e\u0440 \u043f\u043e\u044f\u0432\u0438\u0442\u0441\u044f \u0438 \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438 Claude \u043d\u0430 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435."},
gqH(){return"\u0410\u0434\u0440\u0435\u0441 \u043a\u043e\u043d\u043d\u0435\u043a\u0442\u043e\u0440\u0430"},
gqS(){return"\u0415\u0441\u043b\u0438 \u043a\u043d\u043e\u043f\u043a\u0430 \u043d\u0435 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442: \u0432 Claude \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 Customize \u203a Connectors \u203a Add custom connector \u0438 \u0432\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u044d\u0442\u043e\u0442 \u0430\u0434\u0440\u0435\u0441."},
gqV(){return"\u0420\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0441\u043e \u0432\u0441\u0435\u043c\u0438 \u0442\u0430\u0440\u0438\u0444\u0430\u043c\u0438 Claude, \u0432\u043a\u043b\u044e\u0447\u0430\u044f \u0431\u0435\u0441\u043f\u043b\u0430\u0442\u043d\u044b\u0439. \u0414\u043b\u044f \u0432\u0430\u0448\u0435\u0433\u043e \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u0430 Cursus \u043d\u0443\u0436\u043d\u0430 \u0430\u043a\u0442\u0438\u0432\u043d\u0430\u044f \u043f\u043e\u0434\u043f\u0438\u0441\u043a\u0430 (\u0438\u043b\u0438 \u043f\u0440\u043e\u043c\u043e\u043a\u043e\u0434)."},
gqT(){return"\u0415\u0449\u0451 \u043e\u0434\u0438\u043d \u0448\u0430\u0433: \u0447\u0442\u043e\u0431\u044b Claude \u0432\u0430\u0441 \u0443\u0437\u043d\u0430\u043b, \u043f\u0440\u0438\u0432\u044f\u0436\u0438\u0442\u0435 Google \u043a \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u0443 Cursus."},
gpQ(){return"\u0412\u0445\u043e\u0434 \u0447\u0435\u0440\u0435\u0437 Apple \u0432\u043a\u043b\u044e\u0447\u0451\u043d"},
gpW(){return"\u0412\u0445\u043e\u0434\u0438\u0442\u044c \u0442\u0430\u043a\u0436\u0435 \u0447\u0435\u0440\u0435\u0437 Apple"},
gpX(){return"\u0427\u0442\u043e\u0431\u044b \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0442\u044c \u044d\u0442\u043e\u0442 \u0436\u0435 \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u0447\u0435\u0440\u0435\u0437 Apple, \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u043c \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435 \u0438\u043b\u0438 \u0432 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435."},
gq0(){return"\u0412\u0445\u043e\u0434 \u0447\u0435\u0440\u0435\u0437 Apple \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d: \u0430\u043a\u043a\u0430\u0443\u043d\u0442 \u0442\u0435\u043f\u0435\u0440\u044c \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0438 \u0447\u0435\u0440\u0435\u0437 Apple."},
gpZ(){return"\u0423 \u044d\u0442\u043e\u0433\u043e Apple ID \u0443\u0436\u0435 \u0435\u0441\u0442\u044c \u0441\u0432\u043e\u0439 \u0430\u043a\u043a\u0430\u0443\u043d\u0442 Cursus. \u0415\u0441\u043b\u0438 \u043e\u043d \u043f\u0443\u0441\u0442\u043e\u0439, \u043e\u0442\u043a\u0440\u043e\u0439\u0442\u0435 Cursus \u0447\u0435\u0440\u0435\u0437 Apple, \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \xab\u0423\u0434\u0430\u043b\u0438\u0442\u044c \u043c\u043e\u0439 \u0430\u043a\u043a\u0430\u0443\u043d\u0442\xbb (\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u203a \u0421\u0438\u043d\u0445\u0440\u043e\u043d\u0438\u0437\u0430\u0446\u0438\u044f) \u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u0435 \u043f\u043e\u043f\u044b\u0442\u043a\u0443 \u0437\u0434\u0435\u0441\u044c."},
gqK(){return"Claude \u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0451\u043d \u043a \u0432\u0430\u0448\u0435\u043c\u0443 \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u0443."},
qR(a){return"\u041f\u043e\u0441\u043b\u0435\u0434\u043d\u044f\u044f \u0430\u043a\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c: "+a},
gqU(){return"Claude \u0435\u0449\u0451 \u043d\u0435 \u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0451\u043d \u043a \u044d\u0442\u043e\u043c\u0443 \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u0443."},
gty(){return"\u041f\u0435\u0440\u0432\u043e\u0435 \u043f\u043e\u043b\u0435 \u0441\u043b\u0443\u0436\u0438\u0442 \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u043e\u043c"},
gtz(){return"\u0417\u0430\u0433\u043e\u043b\u043e\u0432\u043e\u043a \u0441\u0442\u0440\u043e\u043a"},
gtB(){return"\u0423\u0432\u0435\u0434\u043e\u043c\u043b\u0435\u043d\u0438\u0435 \u043d\u0435 \u043c\u043e\u0436\u0435\u0442 \u0441\u043b\u0443\u0436\u0438\u0442\u044c \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u043e\u043c."},
gtr(){return"\u041f\u043e\u043b\u044f \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f"},
gts(){return"\u0423\u0434\u0430\u043b\u0451\u043d\u043d\u044b\u0435 \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u043d\u044b\u0435 \u043f\u043e\u043b\u044f: \u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \u043e\u0434\u043d\u043e, \u0447\u0442\u043e\u0431\u044b \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u0435\u0433\u043e \u0441\u043d\u043e\u0432\u0430. \u041f\u0440\u0435\u0436\u043d\u0438\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u0432\u0435\u0440\u043d\u0443\u0442\u0441\u044f."},
rN(a){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c \xab"+a+"\xbb?"},
grL(){return"\u0423\u0434\u0430\u043b\u0438\u0442\u044c"},
grM(){return"\u041e\u043d\u043e \u0438\u0441\u0447\u0435\u0437\u043d\u0435\u0442 \u0438\u0437 \u0432\u0441\u0435\u0445 \u0444\u043e\u0440\u043c \u0438 \u0441\u0442\u0440\u043e\u043a. \u041f\u0440\u0438 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438 \u043f\u043e\u0437\u0436\u0435 \u043c\u043e\u0436\u043d\u043e \u0441\u043e\u0437\u0434\u0430\u0442\u044c \u043d\u043e\u0432\u043e\u0435 \u043f\u043e\u043b\u0435."},
grX(){return"\u0415\u0441\u043b\u0438 \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u043e\u043c \u0441\u043b\u0443\u0436\u0438\u0442 \u0434\u0440\u0443\u0433\u043e\u0435 \u043f\u043e\u043b\u0435, \u043d\u0430\u0437\u0432\u0430\u043d\u0438\u0435 \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043f\u043e\u0434 \u043d\u0438\u043c \u0432 \u0441\u0442\u0440\u043e\u043a\u0435."},
grO(){return"\u0412\u0441\u0435\u0433\u0434\u0430 \u0435\u0441\u0442\u044c: \u044d\u0442\u043e \u043f\u043e\u043b\u0435 \u043d\u0435\u043b\u044c\u0437\u044f \u0443\u0431\u0440\u0430\u0442\u044c \u0438\u043b\u0438 \u0443\u0434\u0430\u043b\u0438\u0442\u044c."},
