go7(){return"\u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e"},
grH(){return"\u041d\u0435\u0442"},
grF(){return"\u041e\u0442\u043c\u0435\u0447\u0435\u043d\u043e \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e"},
grG(){return"\u0421\u043d\u0430\u0447\u0430\u043b\u0430 \u0434\u043e\u0431\u0430\u0432\u044c\u0442\u0435 \u0432\u0430\u0440\u0438\u0430\u043d\u0442\u044b \u0432\u044b\u0448\u0435."},
gte(){return"\u0415\u0434\u0438\u043d\u0438\u0446\u0430"},
gtf(){return"\u041d\u0430\u043f\u0440. \u0431\u0430\u043b\u043b, \u043c\u0438\u043d"},
gof(){return"\u041f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430"},
grU(){return"\u041d\u0430\u043f\u0440. \u0441. 12\u201315"},
grI(){return"\u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435 \u043f\u043e \u0443\u043c\u043e\u043b\u0447\u0430\u043d\u0438\u044e \u043f\u043e\u0434\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0432 \u043d\u043e\u0432\u044b\u0435 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u044b; \u0443\u0436\u0435 \u0441\u043e\u0437\u0434\u0430\u043d\u043d\u044b\u0435 \u043d\u0435 \u043c\u0435\u043d\u044f\u044e\u0442\u0441\u044f. \u041f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430 \u0432\u0438\u0434\u043d\u0430 \u0441\u0435\u0440\u044b\u043c \u0432 \u043f\u0443\u0441\u0442\u043e\u043c \u043f\u043e\u043b\u0435."},
gti(){return"\u0412\u044b\u0431\u0435\u0440\u0438\u0442\u0435, \u0447\u0442\u043e \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c: \u043e\u0441\u0442\u0430\u043d\u0443\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043e\u0434\u0445\u043e\u0434\u044f\u0449\u0438\u0435 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u044b. \u0412 \u0441\u043a\u043e\u0431\u043a\u0430\u0445 \u2014 \u0438\u0445 \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u043e."},
vt(a){return"\u041d\u0435\u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u043e: \u0438\u043d\u0430\u0447\u0435 \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u043e\u043c \u0431\u0443\u0434\u0435\u0442 \xab"+a+"\xbb"},
gvu(){return"\u041d\u0430 \u0437\u0430\u0432\u0442\u0440\u0430 \u043d\u0438\u0447\u0435\u0433\u043e."},
